+// Till sales: importing sold dishes consumes their recipes' ingredients
+// once per ticket, all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000 + 0;
+
+/** Records parsed sale rows, consumes stock once per ticket, and returns { tickets, dishes }. */
+export function recordSales(store, rows) {
+  const existing = new Set((store.data.sales ?? []).map((s) => s.ticket));
+  const pending = rows.filter((r) => !existing.has(r.ticket));
+
+  const remaining = new Map();
+  const plan = [];
+  for (const r of pending) {
+    if (!Number.isInteger(r.qty) || r.qty < 1) throw new AppError("invalid_qty");
+    const dish = getDish(store, r.dishId);
+    const recipe = getRecipe(store, dish.recipeId);
+    const needs = scaled(recipe, r.qty);
+    for (const n of needs) {
+      if (n.qty <= 0) continue;
+      const item = getItem(store, n.itemId);
+      const avail = remaining.has(n.itemId) ? remaining.get(n.itemId) : round3(onHand(store, n.itemId));
+      if (avail < n.qty) {
+        if (r.row) throw new AppError("sale_not_enough_stock", { row: r.row, item: item.name, available: avail, unit: item.unit });
+        throw new AppError("not_enough_stock", { item: item.name, available: avail, unit: item.unit });
+      }
+      remaining.set(n.itemId, round3(avail - n.qty));
+    }
+    plan.push({ ticket: r.ticket, soldAt: r.soldAt, dishId: r.dishId, qty: r.qty, needs });
+  }
+
+  store.data.sales ??= [];
+  const tickets = new Set();
+  let dishes = 0;
+  for (const p of plan) {
+    for (const n of p.needs) {
+      if (n.qty > 0) consume(store, n.itemId, n.qty, { at: p.soldAt, ref: `sale:${p.ticket}` });
+    }
+    store.data.sales.push({ id: store.nextId("sale"), ticket: p.ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty });
+    tickets.add(p.ticket);
+    dishes += p.qty;
+  }
+  return { tickets: tickets.size, dishes };
+}
