@@ -0,0 +1,32 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty).
+// Checks every row and available stock before importing anything;
+// tickets already imported are skipped.
+import { isInstant } from "../dates.js";
+import { recordSales } from "../domain/sales.js";
+import { AppError } from "../errors.js";
+import { parseCsv, parseCsvObjects } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports sales CSV; returns { tickets, dishes } counts or throws naming the row. */
+export function importSales(store, text) {
+  const [head = []] = parseCsv(text);
+  if (!head.length) return { tickets: 0, dishes: 0 };
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+
+  const dishes = new Set((store.data.dishes ?? []).map((d) => d.id));
+  const clean = parseCsvObjects(text).map((r, i) => {
+    const where = `row ${i + 2}`;
+    if (!r.ticket) throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(r.soldAt)) throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    const dishId = Number(r.dishId);
+    if (!r.dishId || !Number.isInteger(dishId) || dishId < 1) throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    if (!dishes.has(dishId)) throw new AppError("bad_request", { reason: `${where}: unknown dish ${r.dishId}` });
+    const qty = Number(r.qty);
+    if (!r.qty || !Number.isInteger(qty) || qty < 1) throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    return { row: where, ticket: r.ticket, soldAt: new Date(r.soldAt).toISOString(), dishId, qty };
+  });
+
+  return recordSales(store, clean);
+}
